CREATE OR REPLACE FUNCTION public.seller_payout_dates(p_orders uuid[])
 RETURNS TABLE(order_id uuid, available_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
